  dplyr::mutate(
    GB = dplyr::if_else(GB == 0.0, "-", sprintf("%.1f", GB)),
    run_diff_display = paste0(run_diff, "||", total_rs, "-", total_ra)
  ) |>
  cbbplotR::gt_cbb_teams(team, team) |> 
  dplyr::arrange(-Win_Pct, -run_diff) |> 
  gt::gt() |> 
